import os,sys,pathlib
sys.path.insert(0, str(pathlib.Path(os.environ.get("TEMP", "/tmp")) / "minibars-lua-runtime"))
from lupa.lua51 import LuaRuntime
lua=LuaRuntime()
lua.execute("frames = {}; SlashCmdList = {}; clock = 100; auras = {}\nlocal methods = {}\nfunction methods:SetScript(k,v) self.scripts[k]=v end\nfunction methods:GetWidth() return self.width or 140 end\nfunction methods:GetEffectiveScale() return 1 end\nfunction methods:GetFrameLevel() return 1 end\nfunction methods:SetSize(w,h) self.width=w end\nfunction methods:SetWidth(w) self.width=w end\nfunction methods:GetCenter() return 700,400 end\nfunction methods:SetValue(v) self.value=v end\nfunction methods:SetMinMaxValues(a,b) self.maximum=b end\nfunction methods:SetText(v) self.text=v end\nfunction methods:SetAlpha(v) self.alpha=v end\nfunction methods:Show() self.visible=true end\nfunction methods:Hide() self.visible=false end\nfunction methods:EnableMouse(v) self.mouse=v end\nfunction methods:CreateFontString() return CreateFrame('Font') end\nsetmetatable(methods,{__index=function() return function() end end})\nfunction CreateFrame(kind,name,parent)\n local f=setmetatable({kind=kind,parent=parent,scripts={}}, {__index=methods})\n frames[#frames+1]=f; if name then _G[name]=f end; return f\nend\nUIParent=CreateFrame('Frame'); Minimap=CreateFrame('Frame'); Minimap.width=160\nfunction GetTime() return clock end\nfunction UnitClass() return 'Paladin','PALADIN' end\nfunction GetSpellInfo(id) return 'Spell'..id end\nfunction UnitBuff(_,i)\n local a=auras[i]; if a then return a.name,nil,nil,nil,a.duration,a.expires,'player',nil,nil,a.id end\nend\nfunction GetNumSpellTabs() return 2 end\nfunction GetSpellTabInfo() return 'Paladin',nil,0,1 end\nfunction GetSpellBookItemInfo() return 'SPELL',1310898 end\n")
lua.execute("cursorX,cursorY,mouseDown=0,0,false\nfunction GetCursorPosition() return cursorX,cursorY end\nfunction IsMouseButtonDown() return mouseDown end\nlocal sample=CreateFrame('Frame'); local m=getmetatable(sample).__index\nfunction m:CreateTexture() return CreateFrame('Texture') end\nfunction m:GetLeft() return 620 end\nfunction m:GetTop() return 410 end\nfunction m:SetSize(w,h) self.width=w; self.height=h end\nfunction m:SetPoint(...) self.point={...} end\n")
lua.execute("local m=getmetatable(CreateFrame('Frame')).__index\nfunction m:SetFont(_,size) self.fontSize=size end\nfunction m:GetStringWidth()\n local width=0\n for c in (self.text or ''):gmatch('[%z\\1-\\127\\194-\\244][\\128-\\191]*') do\n  width=width+(c=='W' and 9 or 4)*(self.fontSize or 12)/12\n end\n return width\nend\n")
lua.execute("targetExists,targetAttackable,targetDead=true,true,false\nfunction UnitExists() return targetExists end\nfunction UnitCanAttack() return targetAttackable end\nfunction UnitIsDeadOrGhost() return targetDead end\n")
lua.execute("local m=getmetatable(CreateFrame('Frame')).__index\nfunction m:SetStatusBarColor(r,g,b,a) self.color={r,g,b,a} end\n")
lua.execute(pathlib.Path("MiniBars.lua").read_text(),"MiniBars")
